import test from 'node:test';import assert from 'node:assert/strict';import {runCompatibilityAudits} from '../runtime-audits.mjs';
test('sealed compatibility audits retain repository-root dynamic import resolution',async()=>{const key='VEX_AI_STARTUP_AUDIT_SOURCE',old=process.env[key];try{process.env[key]="const {hasFeature}=await import('./src/plan-catalog.js');globalThis.vexAuditImportVerified=!hasFeature('plus','aiChat')&&hasFeature('ultimate','aiChat');";await runCompatibilityAudits();assert.equal(globalThis.vexAuditImportVerified,true);}finally{delete globalThis.vexAuditImportVerified;if(old===undefined)delete process.env[key];else process.env[key]=old;}});
